// Inputs arrive in the order the Merge node received them: GA4, GSC now, GSC previous.
const items = $input.all();
const ga4 = items[0].json, now = items[1].json, prev = items[2].json;

// GA4: sum sessions per date range. Rows carry dimensionValues [source, dateRange].
let cur = 0, before = 0;
for (const r of ga4.rows || []) {
  const range = (r.dimensionValues[1] || {}).value; // 'current' | 'previous' (GA4 appends the range name as a dimension)
  const n = Number(r.metricValues[0].value || 0);
  if (range === 'previous') before += n; else cur += n;
}
const multiplier = before > 0 ? Math.round((cur / before) * 10) / 10 : null;

const rowNow = (now.rows || [])[0] || {}, rowPrev = (prev.rows || [])[0] || {};

// Keep the manually tracked tool counts from the current file; this workflow does not know them.
const existing = $('Read current live.json').first()?.json?.tools;

return [{ json: {
  updatedAt: $today.toFormat('yyyy-MM-dd'),
  updatedBy: 'n8n weekly refresh',
  note: 'Written by automation/n8n-live-metrics.json. Raw numbers only; the templates format them.',
  llm: { multiplier: multiplier ?? 22, window: '12 months', source: 'GA4', sessions: cur, sessionsBefore: before },
  gsc: {
    impressionsBefore: Math.round(rowPrev.impressions || 0), impressions: Math.round(rowNow.impressions || 0),
    clicks: Math.round(rowNow.clicks || 0),
    avgPositionBefore: Math.round((rowPrev.position || 0) * 10) / 10, avgPosition: Math.round((rowNow.position || 0) * 10) / 10,
    window: '12 months'
  },
  tools: existing || { queryFanOut: 829, llmQueryBuilder: 149, aiHumanizer: 669 }
} }];
